diff --git a/repro/decl-emit.ts b/repro/decl-emit.ts
new file mode 100644
index 000000000..c554904ec
--- /dev/null
+++ b/repro/decl-emit.ts
@@ -0,0 +1,9 @@
+type Wrapper<T> = { _type: T }
+declare function stringWrapper(): Wrapper<string>;
+declare function objWrapper<T extends Record<string, Wrapper<any>>>(obj: T): Wrapper<T>;
+declare function unwrapAll<T extends Record<string, Wrapper<any>>>(w: Wrapper<T>): { [K in keyof T]: T[K]['_type'] };
+
+const value = objWrapper({ prop1: stringWrapper() as Wrapper<"hello"> });
+export const r = unwrapAll(value);
+// Real type of r.prop1 is "hello" (this compiles), but the emitted .d.ts says Wrapper<"hello">.
+export const check: "hello" = r.prop1;
diff --git a/repro/print-type.js b/repro/print-type.js
new file mode 100644
index 000000000..96e65b42b
--- /dev/null
+++ b/repro/print-type.js
@@ -0,0 +1,30 @@
+// Usage (from repo root): node repro/print-type.js [file.ts]
+// Set TS_PATH to a published typescript.js to compare releases.
+const ts = require(process.env.TS_PATH || "../built/local/typescript.js");
+const path = require("path");
+const file = path.resolve(process.argv[2] || path.join(__dirname, "repro.ts"));
+const options = { strict: true, noEmit: true, types: [], target: ts.ScriptTarget.ESNext };
+const program = ts.createProgram([file], options);
+const checker = program.getTypeChecker();
+const sf = program.getSourceFile(file);
+let alias;
+sf.forEachChild(n => { if (ts.isTypeAliasDeclaration(n) && n.name.text === "Test") alias = n; });
+const t = checker.getTypeAtLocation(alias.name);
+console.log("TypeScript " + ts.version);
+console.log("checker.typeToString(Test)    : " + checker.typeToString(t, undefined, ts.TypeFormatFlags.NoTruncation));
+console.log("typeof Test['prop1'] (checker): " + checker.typeToString(checker.getTypeOfSymbol(t.getProperty("prop1"))));
+
+// Quick info (what the playground / editor hover shows for `Test`)
+const host = {
+    getScriptFileNames: () => [file],
+    getScriptVersion: () => "1",
+    getScriptSnapshot: f => ts.sys.fileExists(f) ? ts.ScriptSnapshot.fromString(ts.sys.readFile(f)) : undefined,
+    getCurrentDirectory: () => process.cwd(),
+    getCompilationSettings: () => options,
+    getDefaultLibFileName: o => ts.getDefaultLibFilePath(o),
+    fileExists: ts.sys.fileExists, readFile: ts.sys.readFile,
+};
+const ls = ts.createLanguageService(host);
+const qi = ls.getQuickInfoAtPosition(file, alias.name.getStart());
+console.log("quickinfo for Test            : " + ts.displayPartsToString(qi.displayParts));
+for (const d of ts.getPreEmitDiagnostics(program)) console.log("error TS" + d.code + ": " + ts.flattenDiagnosticMessageText(d.messageText, "\n"));
diff --git a/repro/repro.ts b/repro/repro.ts
new file mode 100644
index 000000000..7c28a519a
--- /dev/null
+++ b/repro/repro.ts
@@ -0,0 +1,21 @@
+type Wrapper<T> = {
+    _type: T
+}
+
+function stringWrapper(): Wrapper<string> {
+    return { _type: "" }
+}
+
+function objWrapper<T extends Record<string, Wrapper<any>>>(obj: T): Wrapper<T> {
+    return { _type: obj }
+}
+
+const value = objWrapper({
+    prop1: stringWrapper() as Wrapper<"hello">
+})
+
+type Unwrap<T extends Wrapper<any>> = T['_type'] extends Record<string, Wrapper<any>> 
+    ? { [Key in keyof T['_type']]: Unwrap<T['_type'][Key]> } 
+    : T['_type']
+
+type Test = Unwrap<typeof value>
